  const scene=document.createElement('dialog');scene.id='campaignScene';scene.className='panel info-dialog';scene.setAttribute('aria-labelledby','campaignSceneTitle');
  scene.innerHTML='<h2 id="campaignSceneTitle">The dragon above Aurelian</h2><p data-scene-text></p><p class="subtle">This short scene protects every hunter from damage. Controls return when it ends.</p><button class="secondary" data-scene-skip>Skip scene</button><p class="notice" data-scene-error role="status"></p>';
  document.body.append(scene);let busy=false,identity='',generation=0;
  scene.querySelector('[data-scene-skip]').onclick=async()=>{
    if(busy)return;busy=true;const captured=JSON.stringify(session),epoch=generation;scene.querySelector('[data-scene-skip]').disabled=true;
    try{await sendAction('campaignSkip');}catch(e){if(epoch===generation&&captured===JSON.stringify(session))scene.querySelector('[data-scene-error]').textContent=e.message;}
    finally{if(epoch===generation){busy=false;scene.querySelector('[data-scene-skip]').disabled=false;if(captured===JSON.stringify(session))refresh();}}
  };
